import { StyleSheet } from "@formepdf/react";

import type { PdfcnTheme } from "@/registry/types/pdf-themes";

/**
 * Creates compact-mode cell and text styles for the DataTable component.
 * Used when `size="compact"` to render denser rows with smaller font sizes.
 * @param t - The resolved PdfcnTheme instance.
 */
export const createCompactStyles = (t: PdfcnTheme) => {
  const { spacing, fontWeights, lineHeights } = t.primitives;
  return StyleSheet.create({
    cell: {
      paddingHorizontal: spacing[2],
      paddingVertical: spacing[0.5],
    },
    footerText: {
      color: t.colors.foreground,
      fontFamily: t.typography.body.fontFamily,
      fontSize: t.primitives.typography.xs,
      fontWeight: fontWeights.semibold,
      lineHeight: lineHeights.normal,
    },
    headerText: {
      color: t.colors.foreground,
      fontFamily: t.typography.body.fontFamily,
      fontSize: t.primitives.typography.xs,
      fontWeight: fontWeights.semibold,
      lineHeight: lineHeights.normal,
    },
    text: {
      color: t.colors.foreground,
      fontFamily: t.typography.body.fontFamily,
      fontSize: t.primitives.typography.xs,
      lineHeight: lineHeights.normal,
    },
  });
};

/**
 * Converts an arbitrary cell value to a display string.
 * Returns an empty string for null/undefined values.
 * @param value - The raw cell value to format.
 */
export const formatValue = (value: unknown): string => {
  if (value === null || value === undefined) {
    return "";
  }
  if (typeof value === "number") {
    return String(value);
  }
  return String(value);
};

import { Fragment } from "react";

import {
  Table,
  TableBody,
  TableCell,
  TableFooter,
  TableHeader,
  TableRow,
} from "@/registry/bases/forme/components/table/table";
import {
  usePdfcnTheme,
  useSafeMemo,
} from "@/registry/bases/forme/components/theme-provider";
import { Text as PDFText } from "@/registry/bases/forme/lib/pdf-primitives";
import type { Style } from "@/registry/bases/forme/lib/pdf-primitives";

import { createCompactStyles, formatValue } from "./data-table.styles";
import type { DataTableProps } from "./data-table.types";

export const DataTable = <T extends Record<string, unknown>>({
  columns,
  data,
  variant = "grid",
  footer,
  stripe = false,
  size = "default",
  noWrap = false,
  style,
}: DataTableProps<T>) => {
  const theme = usePdfcnTheme();
  const compact = useSafeMemo(() => createCompactStyles(theme), [theme]);
  const isCompact = size === "compact";

  return (
    <Table variant={variant} zebraStripe={stripe} noWrap={noWrap} style={style}>
      <TableHeader>
        <TableRow header>
          {columns.map((col) => (
            <TableCell
              key={col.key}
              header
              align={col.align ?? "left"}
              width={col.width}
              style={isCompact ? compact.cell : undefined}
            >
              {isCompact ? (
                <PDFText
                  style={
                    [
                      compact.headerText,
                      col.align ? ({ textAlign: col.align } as Style) : {},
                    ] as never
                  }
                >
                  {col.header}
                </PDFText>
              ) : (
                col.header
              )}
            </TableCell>
          ))}
        </TableRow>
      </TableHeader>
      <TableBody>
        {data.map((row, i) => (
          // biome-ignore lint/suspicious/noArrayIndexKey: DataTable has no row id; order is stable for static data
          <Fragment key={i}>
            <TableRow>
              {columns.map((col) => {
                const value = row[col.key];
                const rendered = col.render ? col.render(value, row) : null;
                const text = rendered === null ? formatValue(value) : null;
                return (
                  <TableCell
                    key={col.key}
                    align={col.align ?? "left"}
                    width={col.width}
                    style={isCompact ? compact.cell : undefined}
                  >
                    {isCompact
                      ? (rendered ?? (
                          <PDFText
                            style={
                              [
                                compact.text,
                                col.align
                                  ? ({ textAlign: col.align } as Style)
                                  : {},
                              ] as never
                            }
                          >
                            {text}
                          </PDFText>
                        ))
                      : (rendered ?? text)}
                  </TableCell>
                );
              })}
            </TableRow>
          </Fragment>
        ))}
      </TableBody>
      {footer && (
        <TableFooter>
          <TableRow footer>
            {columns.map((col) => {
              const value = col.key in footer ? footer[col.key] : "";
              const rendered = col.renderFooter
                ? col.renderFooter(value)
                : null;
              const text = rendered === null ? formatValue(value) : null;
              return (
                <TableCell
                  key={col.key}
                  footer={!!value}
                  align={col.align ?? "left"}
                  width={col.width}
                  style={isCompact ? compact.cell : undefined}
                >
                  {isCompact
                    ? (rendered ?? (
                        <PDFText
                          style={
                            [
                              value ? compact.footerText : compact.text,
                              col.align
                                ? ({ textAlign: col.align } as Style)
                                : {},
                            ] as never
                          }
                        >
                          {text}
                        </PDFText>
                      ))
                    : (rendered ?? text)}
                </TableCell>
              );
            })}
          </TableRow>
        </TableFooter>
      )}
    </Table>
  );
};

import type React from "react";

import type { TableVariant } from "@/registry/bases/forme/components/table/table.types";
import type { PDFComponentProps } from "@/registry/types/pdf-components";

/** DataTable row density size. */
export type DataTableSize = "default" | "compact";

/**
 * Column definition for a DataTable.
 * Props - `key` | `header` | `align` | `width` | `render` | `renderFooter`
 * @see {@link DataTableColumn}
 */
export interface DataTableColumn<T = Record<string, unknown>> {
  key: keyof T & string;
  header: string;
  align?: "left" | "center" | "right";
  width?: string | number;
  /**
   * Custom cell renderer. Must return @formepdf/react elements (Text, View,
   * Image, etc.) — NOT HTML DOM elements. TypeScript accepts ReactNode but DOM
   * nodes will crash at runtime in the PDF renderer.
   */
  render?: (value: unknown, row: T) => React.ReactNode;
  /**
   * Custom footer cell renderer. Same constraint: return @formepdf/react
   * elements only — no HTML/DOM nodes.
   */
  renderFooter?: (value: unknown) => React.ReactNode;
}

/**
 * Data table for PDF rendering with column definitions, footer support, and stripe options.
 * Props - `columns` | `data` | `variant` | `footer` | `stripe` | `size` | `noWrap` | `style`
 * @see {@link DataTableProps}
 */
export interface DataTableProps<T = Record<string, unknown>> extends Omit<
  PDFComponentProps,
  "children"
> {
  columns: DataTableColumn<T>[];
  data: T[];
  /**
   * @default 'grid'
   */
  variant?: TableVariant;
  footer?: Partial<Record<keyof T & string, string | number>>;
  stripe?: boolean;
  /**
   * @default 'default'
   */
  size?: DataTableSize;
  noWrap?: boolean;
}
